class Solution {
    public String reverseWords(String s) {
        String[] parts = s.split(" ");
        java.util.List<String> words = new java.util.ArrayList<>();
        for (String p : parts) {
            if (!p.isEmpty()) words.add(p);   // 过滤连续空格产生的空串
        }

        StringBuilder sb = new StringBuilder();
        for (int i = words.size() - 1; i >= 0; i--) {
            sb.append(words.get(i));
            if (i > 0) sb.append(' ');      // 单词之间单空格，末尾不加
        }
        return sb.toString();
    }
}

import java.util.*;

class Solution {
    public String reverseWords(String s) {
        // 先 trim 去掉首尾空格，否则切分结果可能带空串
        String t = s.trim();
        // \s+ 把任意长度的空白当成一个分隔符，自动跳过连续空格
        String[] parts = t.split("\\s+");

        List<String> words = new ArrayList<>(Arrays.asList(parts));
        Collections.reverse(words);
        return String.join(" ", words);   // 单词之间单空格
    }
}

class Solution {
    public String reverseWords(String s) {
        char[] c = s.toCharArray();
        int n = c.length;

        // 1. 整体反转
        reverse(c, 0, n - 1);

        // 2. 每个单词内部再反转回来
        int i = 0;
        while (i < n) {
            while (i < n && c[i] == ' ') i++;
            int start = i;
            while (i < n && c[i] != ' ') i++;
            reverse(c, start, i - 1);
        }

        // 3. 原地去空格：read 读原数组，write 写压缩后的位置
        int write = 0, read = 0;
        while (read < n) {
            while (read < n && c[read] == ' ') read++;
            if (read == n) break;
            if (write > 0) c[write++] = ' ';   // 单词之间补一个空格
            while (read < n && c[read] != ' ') {
                c[write++] = c[read++];
            }
        }
        return new String(c, 0, write);
    }

    private void reverse(char[] c, int l, int r) {
        while (l < r) {
            char t = c[l];
            c[l] = c[r];
            c[r] = t;
            l++;
            r--;
        }
    }
}
